\begin{theorem}

	\label{thm:mwis}
	$\STAB(\Mcal)=\widetilde{\STAB}(\Mcal)$ holds if and only if $\Mcal$ has no active dependencies.
	When these equivalent conditions hold, for every quantum state $\rho$,
	\begin{equation}
		\RoM_\Mcal(\rho)=\widetilde{\RoM}_\Mcal(\rho).
		\label{eq:no-active-tight}
	\end{equation}
	Consequently, the polytope relaxation computes the exact reduced robustness without a correction from sign dependencies.
\end{theorem}

\begin{theorem}
	\label{thm:solvable}
	If $\Mcal$ has no active dependencies and $G_\Mcal$ is perfect, then for any $n$-qubit quantum state $\rho$,
	{\small
		\begin{equation}\label{eq:closed-form}
			\RoM_\Mcal\big(\rho\big)
			=
			\max\!\Big(1,\ \max_{Q} \sum_{P\in Q}\big|\tr(P\rho)\big| \Big)
			\le\sqrt{\clnum(G_\Mcal)},
		\end{equation}
	}
	where $Q$ ranges over cliques of $G_\Mcal$, equivalently over pairwise anticommuting subsets of $\Mcal$.
	The bound is attained by any state supported on the $+1$ eigenspace of $|Q|^{-1/2}\sum_{P\in Q}P$ for the maximum clique $Q$.
\end{theorem}

\subsection{Explicit algorithm~\label{sec:algoreducedstab}}
Now that some intuition is gained on how the combinatorial problem of the frustration graph fixes the polytope, we present the general algorithm. The detailed analysis for the runtime is left for Appendix~\ref{proof:Vrepalgo}.
\begin{thm}
    Let $\mathcal M =\{P_1,P_2, \cdots, P_m\}$ be a set of $n$-qubit Pauli strings. There is a classical algorithm, sketched in Alg.~\ref{alg:Vrep}, that takes $\mathcal M$ as an input and outputs the $V$-representation of Thm.~\ref{thm:reducedstabdecomp} with runtime
    \begin{equation}
        T = p(n,m)2^{O(\min\{m,n\}+ \min(m,n^2))}\;,
    \end{equation}
    where $p(n,m)$ is bounded by some polynomial in $n$ and $m$.
    \label{thm:Vrepalgo}
\end{thm}

\begin{algorithm}[H]
\caption{V-representation of STAB($\mathcal{M}$) \label{alg:Vrep}}
    \KwIn{$\mathcal{M} = \{P_1, P_2, \dots, P_m\}$ as the set of Pauli measurements;}
    %\State Input: $\mathcal{M} = \{P_1, P_2, \dots, P_m\}$ as the set of Pauli measurements;
    \KwOut{$\mathrm{stab}(\mathcal M)=\{\vec{v}_1, \vec{v}_2, \dots, \vec{v}_{|\text{stab}(\mathcal{M})|}\}$ as defined on Thm.~\ref{thm:reducedstabdecomp}.}
    Initialize $V \gets \{\;\}$;\\
    Compute $E(G_\mathcal{M})$;\\
    Find $I_{max}(G_\mathcal{M})$;\\
    \For{$S \in I_\mathrm{max}(G_\mathcal M)$}{
        Compute all $f \in B_S$ and append $\vec{v}_{S,f}$ to $V$;
    }
    \Return{V}
\end{algorithm}

As a corollary, we get the complexity of estimating Eq.~\eqref{eq:reducedRoM}: It is known that from the theory of linear programs that finding a $\vec{x} \in \mathbb R^m$ that $\epsilon$-approximates a linear objective with $M$ constraints can be found in $O(m (m+ M)^{3/2}\log(1/\varepsilon))$ time~\cite{vaidya1989speeding}. Then, to estimate the reduced RoM, we first obtain the $V$-representation of the reduced polytope from the set of Pauli measurements via the algorithm of Thm.~\ref{thm:reducedstabdecomp} and then run the linear program with $M =O(2^{\min\{m,n\}+ \min\{cm,(1/2+o(1))n^2\}})$. Since the linear programming runtime dominates due to the extra power of $3/2$, we have:
\begin{cor}
    Given a set of expectation values of $n$-qubit Pauli strings $\mathcal M$ on a quantum state $\psi$, $(\langle P_1\rangle_\psi, \langle P_2\rangle_\psi, \cdots, \langle P_m \rangle_\psi)$, with $m \leq  \mathrm{poly}(n)$, there is an algorithm that $\epsilon$-approximates $\mathrm{RoM}_\mathcal M(\psi)$ in $O(2^{c^\prime \min\{m,n^2\}}\log(1/\epsilon))$ runtime, where $c^\prime=O(1)$. 
\end{cor}

First, we describe the task formulated as what is called a decision problem \footnote{In this section, since we are interested in the complexity-theoretic aspects, assume that all continuous-variable inputs are $\mathrm{poly}(n)$ sized. This includes the Pauli expectation values in Def. \ref{def:stabreducedprob} and the stabilizer probabilities in Def. \ref{def:stabmargprob}. This all can be done by assuming rational inputs.}:
\begin{defn}
    We define the reduced stabilizer membership problem as the decision problem (rSMP) defined by:
    \begin{itemize}
        \item \textbf{Inputs:} A set of $m  \leq \mathrm{poly}(n)$ $n$-qubit Pauli strings, $\mathcal M = \{P_1, P_2, \cdots, P_m\}$ and a vector $\vec{V} \in [-1,1]^m$;
        \item \textbf{Decision:} Output YES if $\vec V \in \mathrm{STAB}(\mathcal M)$ and NO otherwise.
    \end{itemize}
    \label{def:stabreducedprob}
\end{defn}

\begin{thm}
    Denoting $\leq_\mathrm{poly}$ for the polynomial-time reduction, the following are true:
    \begin{enumerate}
        \item $\mathrm{CMP} \leq_\mathrm{poly}\mathrm{SMP}$;
        \item $\mathrm{SMP} \leq_\mathrm{poly} \mathrm{rSMP}$\;.
    \end{enumerate}
    Thus, $\mathrm{CMP} \leq_\mathrm{poly} \mathrm{rSMP}$, and therefore, both $\mathrm{SMP}$ and $\mathrm{rSMP}$ are NP-hard.
    \label{thm:CMPtorSMPreduction}
\end{thm}

\begin{abstract}
Recent results on the non-universality of fault-tolerant gate sets underline the critical role of resource states, such as magic states, to power scalable, universal quantum computation. Here we develop a resource theory, analogous to the theory of entanglement, for resources for stabilizer codes. We introduce two quantitative measures - monotones - for the amount of non-stabilizer resource. As an application we give absolute bounds on the efficiency of magic state distillation. One of these monotones is the sum of the negative entries of the discrete Wigner representation of a quantum state, thereby resolving a long-standing open question of whether the degree of negativity in a quasi-probability representation is an operationally meaningful indicator of quantum behaviour.
\end{abstract}

\begin{defn}
The sum negativity of a state $\rho$ is the sum of the negative elements
of the Wigner function, $\sn{\rho}\equiv\sum_{\boldsymbol{u}:W_{\rho}(\boldsymbol{u})<0}\abs{W_{\rho}\left(\boldsymbol{u}\right)}\equiv\frac{1}{2}\left(\sum_{\boldsymbol{u}}\abs{W_{\rho}\left(\boldsymbol{u}\right)}-1\right)$.

The right hand side of this expression follows because the normalization
of quantum states ($\Tr\rho=1$) implies $\sum_{\boldsymbol{u}}W_{\rho}\left(\boldsymbol{u}\right)=1$.
The advantage of writing the expression in this form is that $\wignorm{\rho}\equiv\sum_{\boldsymbol{u}}\abs{W_{\rho}\left(\boldsymbol{u}\right)}$
is a multiplicative norm and is thus very nice to work with. By this
we mean that the composition law is given as:
\begin{eqnarray}
\wignorm{\rho\otimes\sigma} & = & \sum_{\boldsymbol{u},\boldsymbol{v}}\abs{W_{\rho\otimes\sigma}\left(\boldsymbol{u}\oplus\boldsymbol{v}\right)}\nonumber \\
 & = & \sum_{\boldsymbol{u},\boldsymbol{v}}\abs{W_{\rho}\left(\boldsymbol{u}\right)W_{\sigma}\left(\boldsymbol{v}\right)}\nonumber \\
 & = & \left(\sum_{\boldsymbol{u}}\abs{W_{\rho}\left(\boldsymbol{u}\right)}\right)\left(\sum_{\boldsymbol{v}}\abs{W_{\rho}\left(\boldsymbol{v}\right)}\right).\label{eq:wignorm_composition}
\end{eqnarray}



Since the sum negativity is a linear function of this quantity we
can establish that the former is a magic monotone by showing this
for the latter:\end{defn}
\begin{thm}
The sum negativity is a magic monotone.\end{thm}
\begin{proof}
It suffices to show $\sum_{\boldsymbol{u}}\abs{W_{\rho}\left(\boldsymbol{u}\right)}$
is a magic monotone by verifying the required properties. The main
components are the use of $\rho=\sum_{\boldsymbol{u}}W_{\rho}(\boldsymbol{u})A_{\boldsymbol{u}}$
and the composition identity \ref{eq:wignorm_composition}, which
is the main motivation for working with this quantity rather than
with the sum negativity directly. See appendix \ref{sub:wig_norm_monotone_proof}
for details.

Robustness of Magic (RoM) possesses all the desirable qualities of a resource theoretic measure (see Supplementary Material for proofs of the following). For a mixed stabilizer state, we find $x_i>0$ entailing $ \sum_i | x_i | =  \sum_i  x_i =1  $.  For a non-stabilizer state, at least one $x_i$ is negative and then RoM must exceed unity. Therefore RoM is faithful. Crucially, RoM is non-increasing under stabilizer operations, the free set of operations in the resource theory. 
%All stabilizer operations act as $\sigma_i \rightarrow \sum_j p_{i,j} \sigma_j$ where $\sum_j |p_{i,j}|= \sum_j p_{i,j}=1$. This entails $\rho \rightarrow \sum_{i,j} x_i p_{i,j} \sigma_j $ and we find $\sum_{i,j} |x_i p_{i,j}| = \sum_{i}|x_i|$. Stabilizer operations may decrease RoM as this new stabilizer pseudomixture may not fulfil the minimisation.   
Finally, RoM is submultiplicative, \begin{align}
\mathcal{R}(\rho_1 \otimes \rho_2)&\leq\mathcal{R}(\rho_1)\mathcal{R}(\rho_2), \label{eqn:submult}
\end{align}
which follows by using the minimal stabilizer pseudomixtures for $\rho_1$ and $\rho_2$ to construct a not-necessarily-minimal stabilizer pseudomixture for $\rho_1 \otimes \rho_2$.  Useful lower bounds on $\mathcal{R}(\rho_1 \otimes \rho_2)$ can also be obtained (see Supplementary Material).  

Resource theoretic frameworks are commonplace in quantum information theory, but do not always directly lend themselves to an operational meaningful interpretation or to useful applications in solving relevant problems.  In the next section we show how RoM quantifies the exponential simulation overhead for a version of the Gottesman-Knill protocol where non-stabilizer ancillas $\rho$ can be added to an otherwise stabilizer circuit. The subsequent section discusses RoM's application to the task of implementing non-Clifford operations in an economical way.

\noindent\textit{Robustness quantifies classical simulation overhead.---}
The Gottesman-Knill (GK) theorem shows that for any stabilizer circuit written as a superoperator $\mathcal{E}$ and pure stabilizer state $\sigma_i$, we can efficiently sample from the outcome of a Pauli measurement on $\mathcal{E}(\sigma_i)$.  By collecting many samples, we can estimate the expectation value to any desired accuracy.  If the input state is a probabilistic ensemble of stabilizer states, the Gottesman-Knill theorem still holds provided we can efficiently sample from the ensemble. A Clifford+$T$ circuit suffering very heavy noise can be simulated in this way \cite{buhrman_new_2006,virmani_classical_2005,plenio_upper_2010}. Here we provide a simulation algorithm for estimating an expectation value  $P_{\rho}:=\mathrm{tr}[P\mathcal{E}(\rho)]$ where $\mathcal{E}$ is a stabilizer operation.  The simulation time cost scales with $\sum_i|x_i| \geq \mathcal{R}(\rho)$ where $x_i$ are the quasiprobabilities used (which may be suboptimal).  First, as in \cite{pashayan_estimating_2015}, we use the quasiprobability distribution $x_i$ to form the probability distribution $p_i=|x_i|/\sum_i|x_i|$.  We sample an $i$ value from this probability distribution and use GK to obtain an eigenvalue $m=\pm 1$ for the Pauli measurement on $\mathcal{E}(\sigma_i)$. Our simulation outputs not $m$, but $M=\mathrm{sign}(x_i)m  \sum_i|x_i|$ where $\mathrm{sign}(x_i)=1$ for $x_i>0$ and $\mathrm{sign}(x_i)=-1$ otherwise.  Notice that each run outputs $\pm \sum_i|x_i|$ and not $\pm 1$, which leads to a larger variance of our random variable.  We repeat this sampling process many times and find the mean value of $M$, which gives an unbiased estimator of $P_{\rho}$. 
%However, the variance of outputs from this quasiprobability simulation with outputs $\pm \sum_i|x_i|$ exceeds the inherent variance of Pauli measurements on $\mathcal{E}(\rho)$.  Therefore,  more samples are needed to obtain a precise estimate.  
The Hoeffding inequalities show that for random variables bounded in the interval $[-\sum_i|x_i|,+\sum_i|x_i|]$,  $N$ samples will estimate the mean to within $\delta$ of the actual mean with probability exceeding $1- \epsilon$ where $\epsilon=2 \exp( - N \delta^2 /2 (\sum_i|x_i|)^2)$.  In other words, the desired accuracy is guaranteed by using
\begin{align}
	N = \frac{2}{\delta^2}(\sum_i|x_i|)^2   \ln \left( \frac{2}{\epsilon} \right)\label{eqn:SampleN}	
\end{align}
samples. Using an optimal stabilizer pseudomixture, the number of samples scales quadratically in the robustness, though the robustness typically scales exponentially in the number of magic states.  For each of these samples, the GK scheme requires a polynomial amount of time provided we know how to efficiently sample from the quasiprobabilitiy distribution.
